// regra — HTTP do PNCP com Never Error + On Error → continue (plano §5, convenções): código HTTP e erro
// de rede viram DADO aqui, nunca exceção muda. 429 e 5xx (o 503 "JDBC" dura horas, BACKLOG) e erro de rede
// pedem uma espera de 30 s e UMA nova tentativa; o 429 do PNCP vem em HTML, sem Retry-After.
const TENTATIVA = 1;
const r = $json || {};
const lic = $('Uma por vez').item.json;
const status = r.statusCode ?? null;
let erroRede = null;
if (r.error) {
  const e = r.error;
  erroRede = String(e.message || e.description || e.code || JSON.stringify(e)).slice(0, 300);
}
let docs = null;
if (erroRede === null && status !== null && status >= 200 && status < 300) {
  if (Array.isArray(r.body)) docs = r.body;
  else if (status === 204 || r.body === '' || r.body === null || r.body === undefined) docs = [];
}
const repetir = TENTATIVA === 1 && docs === null
  && (erroRede !== null || status === 429 || (status !== null && status >= 500));
return { json: {
  controle: lic.controle, cnpj: lic.cnpj, ano: lic.ano, seq: lic.seq, estado: lic.estado,
  conhecidos: lic.conhecidos || [], n_arquivos: lic.n_arquivos, rodada_id: lic.rodada_id,
  tentativa: TENTATIVA, http_status: status, erro_rede: erroRede, docs, repetir,
} };

