// regra — seqs ativos no PNCP − seqs que o banco conhece (scripts/28_baixar_licitacao.py:798-803,
// mudou_no_portal). Conhecido = TODO arquivo com sequencialDocumento, inclusive os recusados por teto ou
// formato (senão o mesmo arquivo seria acusado de novo toda semana). statusAtivo === false não conta
// (pncp.py:365-375; o 28 usa `is not False`); nunca iterar 1..N (pncp.py:10, RN-07).
// Sem resposta do PNCP é "não conferida" — nunca "sem novidade" (ADR-007: NADA VISTO ≠ NADA A FAZER).
const x = $json;
const base = { controle: x.controle, estado_antes: x.estado, http_status: x.http_status, tentativas: x.tentativa,
  conhecidos: x.conhecidos || [] };
if (x.docs === null) {
  const motivo = x.erro_rede ? 'rede: ' + x.erro_rede : 'PNCP respondeu HTTP ' + x.http_status;
  return { json: { ...base, resultado: 'nao_conferida', motivo, novos: [] } };
}
if (x.estado === 'falha_rede' && !Number(x.n_arquivos)) {
  return { json: { ...base, resultado: 'nao_comparavel', novos: [],
    motivo: 'nunca baixada (falha_rede sem arquivo conhecido): não há com o que comparar; o W10 já retenta' } };
}
const conhecidos = (x.conhecidos || []).map(Number);
const vistos = [];
const novos = [];
for (const d of x.docs) {
  if (!d || d.statusAtivo === false || d.sequencialDocumento === null || d.sequencialDocumento === undefined) continue;
  const seq = Number(d.sequencialDocumento);
  if (!Number.isFinite(seq) || vistos.includes(seq)) continue;
  vistos.push(seq);
  if (!conhecidos.includes(seq)) {
    novos.push({ seq, titulo: String(d.titulo || '').slice(0, 200),
      tipo: d.tipoDocumentoNome || d.tipoDocumentoDescricao || null, publicado_pncp: d.dataPublicacaoPncp || null });
  }
}
novos.sort((a, b) => a.seq - b.seq);
if (!novos.length) return { json: { ...base, resultado: 'sem_novidade', motivo: null, novos: [], ativos: vistos.length } };
return { json: { ...base, resultado: 'documento_novo', motivo: 'W70: documento novo no PNCP', novos, ativos: vistos.length } };

// regra — a rodada diz o que viu e o que NÃO viu (ADR-007): "sem resposta do PNCP" não é "sem novidade";
// se nenhuma foi conferida, a rodada foi cega. O que passou do limite já está em contadores (Abrir rodada).
const itens = $input.all().map((i) => i.json).filter((x) => x && x.controle);
const de = (r) => itens.filter((x) => x.resultado === r);
const docNovo = de('documento_novo');
const retificadas = docNovo.filter((x) => x.evento_id !== null && x.evento_id !== undefined);
const semTransicao = docNovo.filter((x) => x.evento_id === null || x.evento_id === undefined);
const naoConferidas = de('nao_conferida');
const cego = itens.length > 0 && naoConferidas.length === itens.length;
return [{ json: {
  status: cego ? 'cego' : (naoConferidas.length ? 'parcial' : 'ok'),
  cego,
  contadores: {
    tentadas: itens.length,
    conferidas: itens.length - naoConferidas.length,
    sem_novidade: de('sem_novidade').length,
    sem_novidade_controles: de('sem_novidade').map((x) => x.controle),
    retificadas: retificadas.length,
    retificadas_controles: retificadas.map((x) => ({ controle: x.controle,
      novos: (x.novos || []).map((n) => n.seq), evento_id: String(x.evento_id) })),
    documento_novo_sem_transicao: semTransicao.map((x) => ({ controle: x.controle, estado: x.estado_antes })),
    nao_conferidas: naoConferidas.length,
    nao_conferidas_controles: naoConferidas.map((x) => ({ controle: x.controle, motivo: x.motivo })),
    nao_comparaveis: de('nao_comparavel').map((x) => x.controle),
  },
} }];
